/* Original, local teaching models. Small examples expose mechanisms, not deployable cryptography. */
(() => {
  'use strict';
  const models=window.CourseFigureRegistry;
  const ctl=(id,label,min,max,step,value,unit='')=>({id,label,min,max,step,value,unit});
  const modpow=(base,exponent,modulus)=>{let n=1;for(let i=0;i<exponent;i++)n=n*base%modulus;return n;};
  const birthday=(n,bits)=>n>2**bits?1:-Math.expm1(-n*(n-1)/(2*2**bits));
  const dns=(guesses,portBits)=>-Math.expm1(guesses*Math.log1p(-1/(2**(16+portBits))));
  const tcp=(seq,ack,request,response)=>({serverSeq:ack,serverAck:(seq+request)>>>0,nextServer:(ack+response)>>>0,nextClient:(seq+request)>>>0});
  const budget=(received,sent)=>Math.max(0,3*received-sent);
  const password=(bits,cost,workers)=>2**(bits-1)*cost/(1e6*workers);
  const flood=(mbps,bytes,amplification)=>({pps:mbps*1e6/(8*bytes),victimMbps:mbps*amplification});
  const worm=(initial,doubling,minutes,limit)=>Math.min(limit,initial*2**(minutes/doubling));
  const bestRoute=(preference,specific,reject)=>({best:preference>100?'A':'B',forward:specific&&!reject?'C':preference>100?'A':'B'});
  const close=(a,b)=>Math.abs(a-b)<1e-10*Math.max(1,Math.abs(a),Math.abs(b));
  const box=(U,x,y,w,h,label,color=U.C.a)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="none" stroke="${color}" stroke-width="2"/>`+U.text(x+w/2,y+h/2+5,label,'middle');
  const rows=(U,title,lines)=>U.svg(U.text(40,35,title)+lines.map((s,i)=>U.text(40,85+45*i,s)).join(''),title,800,110+45*lines.length);
  const pct=p=>(100*p).toPrecision(4)+'%';
  const duration=seconds=>seconds<60?seconds.toPrecision(4)+' s':seconds<86400?(seconds/3600).toPrecision(4)+' hours':(seconds/86400/365.25).toPrecision(4)+' years';
  window.CourseSecurityMath={modpow,birthday,dns,tcp,budget,password,flood,worm,bestRoute};

  models.push({id:'mode-reuse',controls:[ctl('messageA','Plaintext A (one byte)',0,255,1,65),ctl('messageB','Plaintext B (one byte)',0,255,1,66),ctl('mask','Repeated keystream byte',0,255,1,170)],
    render(v,U){const a=v.messageA^v.mask,b=v.messageB^v.mask,hex=n=>'0x'+n.toString(16).padStart(2,'0').toUpperCase();return{svg:rows(U,'Reuse cancels the same XOR mask',[`A = ${hex(v.messageA)}; K = ${hex(v.mask)}; ciphertext A = ${hex(a)}`,`B = ${hex(v.messageB)}; K = ${hex(v.mask)}; ciphertext B = ${hex(b)}`,`ciphertext A XOR ciphertext B = ${hex(a^b)}`,`plaintext A XOR plaintext B = ${hex(v.messageA^v.messageB)}`]),stats:[['Ciphertext A',hex(a)],['Ciphertext B',hex(b)],['Leaked relation',hex(a^b)]],equation:'CA = PA ⊕ K; CB = PB ⊕ K; CA ⊕ CB = PA ⊕ PB',note:'One byte of an XOR stream illustrates reusing the same key/nonce/counter keystream. If PA is known, PB = CA ⊕ CB ⊕ PA. Each value is an integer byte. Real CTR uses a block cipher to produce a much longer keystream; changing its nonce prevents this repeated-mask relation.'};},checks:()=>[{name:'Same mask cancels under XOR',pass:((65^170)^(66^170))===(65^66)},{name:'Known plaintext recovers paired byte',pass:((65^170)^(66^170)^65)===66}]});

  models.push({id:'birthday-bound',controls:[ctl('bits','Hash output length',16,64,8,32,'bits'),ctl('logCount','log₁₀ number of messages',0,6,.25,4,'')],
    render(v,U){const n=Math.round(10**v.logCount),p=birthday(n,v.bits);return{svg:U.plot([{name:'Birthday approximation',points:U.range(180,t=>{const q=Math.round(10**(6*t));return[Math.log10(q),100*birthday(q,v.bits)];})},{name:'Chosen message count',color:U.C.b,points:[[Math.log10(n),0],[Math.log10(n),100]]}],{xmin:0,xmax:6,ymin:0,ymax:100,xlabel:'log₁₀ message count q',ylabel:'Collision probability (%)',title:'Any colliding pair among q independent hash outputs'}),stats:[['Messages q',n.toLocaleString('en-US')],['Approximate probability',pct(p)],['50% scale',Math.round(Math.sqrt(2*Math.log(2)*2**v.bits)).toLocaleString('en-US')+' messages']],equation:'P(any collision) ≈ 1 − exp[−q(q−1)/(2·2ᵇ)]; q₅₀ ≈ √(2 ln(2)·2ᵇ)',note:'b is output bits; q distinct messages have independent uniform outputs. This pair-count approximation is most accurate when q is small relative to 2ᵇ. The pigeonhole bound gives probability 1 for q > 2ᵇ. A collision allows choosing both messages; a preimage fixes a target hash first.'};},checks:()=>[{name:'One output has zero pair collisions',pass:birthday(1,32)===0},{name:'50 percent collision scale',pass:Math.abs(birthday(77163,32)-.5)<.00002},{name:'Beyond output space collision is certain',pass:birthday(65537,16)===1}]});

  models.push({id:'diffie-hellman',controls:[ctl('alice','Alice private exponent a',1,20,1,6),ctl('bob','Bob private exponent b',1,20,1,15)],
    render(v,U){const A=modpow(5,v.alice,23),B=modpow(5,v.bob,23),ka=modpow(B,v.alice,23),kb=modpow(A,v.bob,23);return{svg:rows(U,'Public parameters p = 23 and g = 5',[`Alice keeps a = ${v.alice}; sends A = 5ᵃ mod 23 = ${A}`,`Bob keeps b = ${v.bob}; sends B = 5ᵇ mod 23 = ${B}`,`Alice computes Bᵃ mod 23 = ${ka}`,`Bob computes Aᵇ mod 23 = ${kb}`]),stats:[['Alice public value',String(A)],['Bob public value',String(B)],['Shared result',String(ka)]],equation:'A = gᵃ mod p; B = gᵇ mod p; Bᵃ = Aᵇ = gᵃᵇ (mod p)',note:'Tiny integer arithmetic exposes the agreement; these parameters are easily brute-forced. Real protocols validate public values, use strong groups and derive traffic keys with a KDF. Authentication binds the exchange to an identity. An unauthenticated intermediary can establish separate agreements with each peer.'};},checks:()=>[{name:'Reference public values and shared result',pass:modpow(5,6,23)===8&&modpow(5,15,23)===19&&modpow(19,6,23)===2},{name:'All illustrated exponent pairs agree',pass:Array.from({length:20},(_,i)=>i+1).every(a=>Array.from({length:20},(_,i)=>i+1).every(b=>modpow(modpow(5,a,23),b,23)===modpow(modpow(5,b,23),a,23)))}]});

  models.push({id:'vpn-layers',controls:[ctl('nested','Tunnel architecture',0,1,1,1,'0 chain / 1 nested'),ctl('observer','Observing provider',1,2,1,1,'1 entry / 2 exit'),ctl('https','Application uses HTTPS',0,1,1,1,'0 no / 1 yes')],
    render(v,U){const content=v.https?'TLS records; application plaintext encrypted':'Application plaintext visible',entry=v.nested?'Inner VPN ciphertext; exit address visible':content,seen=v.observer===1?entry:content;return{svg:U.svg(box(U,30,65,160,70,'Client')+box(U,315,65,160,70,'Entry VPN')+box(U,600,65,160,70,'Exit VPN')+U.arrow(190,100,310,100)+U.arrow(475,100,595,100)+U.text(400,35,v.nested?'Nested: client creates both tunnels':'Chain: entry terminates and forwards','middle')+U.text(40,190,'Observer: '+(v.observer===1?'entry provider':'exit provider'))+U.text(40,235,seen)+U.text(40,280,v.observer===1?(v.nested?'Entry sees client IP and exit IP.':'Entry sees client, exit and final destination IPs.'):'Exit sees entry IP and destination IP.'),'VPN termination determines which layer a provider can inspect',800,320),stats:[['Architecture',v.nested?'Nested tunnels':'Provider chain'],['Observer',v.observer===1?'Entry':'Exit'],['Application protection',v.https?'TLS inside VPN':'Plaintext inside VPN']],equation:v.nested?'Client → outer VPN[ inner VPN[ application ] ] → entry → inner VPN → exit':'Client → VPN[ application ] → entry → VPN[ application ] → exit',note:'Two independently operated providers, correctly routed traffic, and a remote exit are assumed. In the chain case the entry initiates the next tunnel after terminating the first. In the nested case the client-to-exit inner tunnel crosses the entry. Exit visibility applies after inner decryption. Traffic timing, volume, collusion and endpoint compromise remain relevant to both architectures; DNS follows the intended exit route here.'};}});

  models.push({id:'route-policy',controls:[ctl('preference','Route A LOCAL_PREF',50,300,25,200),ctl('specific','Additional matching /25 route',0,1,1,0,'0 absent / 1 present'),ctl('reject','Reject ROV-invalid routes',0,1,1,1,'0 no / 1 yes')],
    render(v,U){const r=bestRoute(v.preference,v.specific,v.reject);return{svg:rows(U,'Destination 198.51.100.42 matches both example prefixes',[`A: 198.51.100.0/24; preference ${v.preference}; AS_PATH length 4`,`B: 198.51.100.0/24; preference 100; AS_PATH length 2`,`Same-prefix BGP winner: ${r.best}`,`C: matching /25, ROV Invalid; ${v.specific?(v.reject?'filtered before installation':'installed'):'absent'}`,`ROV-invalid import policy: ${v.reject?'reject':'accept'}`,`Forwarding uses route ${r.forward}`]),stats:[['Best /24',r.best],['Matching /25',v.specific?(v.reject?'Rejected':'Installed'):'Absent'],['Packet next hop',r.forward]],equation:'For one prefix: higher LOCAL_PREF, then shorter AS_PATH in this model. Forwarding: longest installed matching prefix.',note:'Three illustrative routes, equal other attributes, eligible next hops and one routing table are assumed. A and B are origin-valid; C is origin-invalid and covers the lower half of the /24. The reject control models a local import policy. ROV checks origin authorization and allowed prefix length, while AS_PATH authentication is a separate question.'};},checks:()=>[{name:'Local preference can outweigh path length',pass:bestRoute(200,0,1).best==='A'},{name:'Equal preference chooses shorter path',pass:bestRoute(100,0,1).best==='B'},{name:'Installed more specific wins forwarding',pass:bestRoute(300,1,0).forward==='C'},{name:'Invalid rejection removes specific route',pass:bestRoute(300,1,1).forward==='A'}]});

  models.push({id:'tcp-ledger',controls:[ctl('clientSeq','Client segment SEQ',0,9000,100,1200,'byte index'),ctl('serverSeq','Client segment ACK',0,9000,100,4600,'byte index'),ctl('request','Client payload length',0,200,5,75,'bytes'),ctl('response','Server payload length',0,100,5,30,'bytes')],
    render(v,U){const t=tcp(v.clientSeq,v.serverSeq,v.request,v.response);return{svg:U.svg(U.text(65,35,'Client byte space')+U.text(560,35,'Server byte space')+U.line(100,65,100,275,U.C.muted)+U.line(680,65,680,275,U.C.muted)+U.arrow(100,95,680,150)+U.text(390,80,`SEQ ${v.clientSeq}; ACK ${v.serverSeq}; ${v.request} bytes`,'middle')+U.arrow(680,205,100,260,U.C.b)+U.text(390,192,`SEQ ${t.serverSeq}; ACK ${t.serverAck}; ${v.response} bytes`,'middle')+U.text(400,305,`Next client SEQ ${t.nextClient}; next server SEQ ${t.nextServer}`,'middle'),'A request advances the client byte counter; a response advances the server byte counter',800,340),stats:[['Server reply SEQ',String(t.serverSeq)],['Server reply ACK',String(t.serverAck)],['Server next SEQ',String(t.nextServer)]],equation:'Reply SEQ = incoming ACK; reply ACK = incoming SEQ + client payload bytes; next server SEQ = reply SEQ + server payload bytes (mod 2³²).',note:'Established connection, in-order delivery, all earlier data acknowledged, no loss, no other in-flight bytes, SYN/FIN absent and immediate response. ACK is the next byte expected in the opposite direction. Payload length excludes Ethernet, IP and TCP headers. SYN or FIN each adds one to its sender’s sequence-space consumption; a pure ACK adds zero.'};},checks:()=>{const t=tcp(1000,3000,50,15);return[{name:'Independent request and response counters',pass:t.serverSeq===3000&&t.serverAck===1050&&t.nextServer===3015},{name:'Pure ACK consumes zero',pass:tcp(1000,3000,0,0).serverAck===1000},{name:'32-bit wraparound',pass:tcp(4294967290,3000,10,0).serverAck===4}];}});

  models.push({id:'dns-race',controls:[ctl('portBits','Random source-port entropy',0,16,1,14,'bits'),ctl('guesses','Forged replies before real reply',0,100000,1000,10000,'guesses')],
    render(v,U){const p=dns(v.guesses,v.portBits),space=2**(16+v.portBits);return{svg:rows(U,'One unanswered DNS query: guess the transaction ID and source port',[`Transaction ID: 16 random bits; source port: ${v.portBits} random bits`,`Effective pair space M = ${space.toLocaleString('en-US')}`,`q = ${v.guesses.toLocaleString('en-US')} independent forged replies`,`Chance of at least one matching pair: ${pct(p)}`]),stats:[['Guess space',space.toLocaleString('en-US')],['Success probability',pct(p)],['Unpredictability',16+v.portBits+' bits']],equation:'M = 2^(16 + portBits); P(success) = 1 − (1 − 1/M)^q',note:'One fixed outstanding query, uniform independent ID/port choices and guesses with replacement. The other required fields already match, forged packets arrive in the reply window, and DNSSEC validation is absent. Repeated outstanding queries, NAT port behavior, bias and packet limits change the result. DNSSEC signatures introduce a separate data-authenticity validation stage.'};},checks:()=>[{name:'Zero guesses give zero success',pass:dns(0,14)===0},{name:'One guess matches inverse space',pass:close(dns(1,0),1/65536)},{name:'Port entropy reduces success',pass:dns(10000,14)<dns(10000,0)}]});

  models.push({id:'quic-budget',controls:[ctl('received','Bytes received from client address',1200,12000,1200,1200,'bytes'),ctl('sent','Bytes already sent to that address',0,36000,1200,2400,'bytes'),ctl('validated','Client address validated',0,1,1,0,'0 no / 1 yes')],
    render(v,U){const left=budget(v.received,v.sent),over=v.sent>3*v.received;return{svg:rows(U,'QUIC server tracks bytes for an unvalidated client address',[`Received R = ${v.received} bytes; already sent S = ${v.sent} bytes`,`Three-times ceiling: 3R = ${3*v.received} bytes`,v.validated?'Address validated: this amplification limit is lifted.':`Additional permitted bytes = max(0, 3R − S) = ${left}`,!v.validated&&over?'Chosen prior sent total exceeds the unvalidated-address limit.':'Congestion control and flow control impose their own limits.']),stats:[['Address state',v.validated?'Validated':'Unvalidated'],['3R byte ceiling',String(3*v.received)],['Additional budget',v.validated?'Amplification cap lifted':left+' bytes']],equation:'Before address validation: S + additional ≤ 3R. Both R and S are cumulative UDP datagram payload bytes counted by QUIC for this address.',note:'Server anti-amplification accounting at one client address; the controls vary cumulative received/sent bytes independently, so an excessive prior-send choice is explicitly flagged. Address validation establishes return reachability. Connection authentication, path validation, congestion control, packet protection and 0-RTT replay handling serve separate purposes.'};},checks:()=>[{name:'1200 received minus 2400 sent permits 1200 more',pass:budget(1200,2400)===1200},{name:'Exhausted budget stays at zero',pass:budget(1200,4800)===0}]});

  models.push({id:'password-cost',controls:[ctl('entropy','Uniform secret search-space size',12,64,4,32,'bits'),ctl('cost','One guess per worker',10,100000,10,1000,'µs'),ctl('workers','Parallel independent workers',1,128,1,8)],
    render(v,U){const seconds=password(v.entropy,v.cost,v.workers),rate=1e6*v.workers/v.cost;return{svg:rows(U,'Offline guesses against one stolen password verifier',[`Uniform candidate space N = 2^${v.entropy}`,`Per-worker guess time = ${v.cost} µs; parallel workers = ${v.workers}`,`Aggregate guess rate = ${rate.toPrecision(4)} guesses/s`,`Mean time, about N/2 guesses: ${duration(seconds)}`]),stats:[['Aggregate rate',rate.toPrecision(4)+' guesses/s'],['Mean search time',duration(seconds)],['Public salt', 'Per-account work']],equation:'G = workers · 10⁶ / costµs; mean time ≈ 2^(h−1) / G seconds',note:'One uniformly selected h-bit secret, guesses without repetition and constant measured per-worker verifier cost. Real passwords have biased distributions; memory-hard KDFs constrain achievable hardware parallelism. A unique public salt prevents reusing one computed verifier across accounts. It adds per-account work while password choice and KDF cost determine this one-account search.'};},checks:()=>[{name:'32 bits, 1 ms and 8 workers give reference mean',pass:close(password(32,1000,8),268435.456)},{name:'Twice the cost doubles time',pass:close(password(32,2000,8)/password(32,1000,8),2)},{name:'Twice the workers halves time',pass:close(password(32,1000,16)/password(32,1000,8),.5)}]});

  models.push({id:'dos-resources',controls:[ctl('mbps','Attacker request traffic',1,100,1,10,'Mbit/s'),ctl('bytes','Request packet accounted size',64,1500,4,100,'bytes'),ctl('amplification','Response/request byte ratio',1,100,1,30,'×')],
    render(v,U){const f=flood(v.mbps,v.bytes,v.amplification);return{svg:U.svg(box(U,30,70,180,70,'Request sender')+box(U,310,70,180,70,'Reflector')+box(U,590,70,180,70,'Victim')+U.arrow(210,105,305,105)+U.arrow(490,105,585,105,U.C.b)+U.text(120,190,v.mbps+' Mbit/s','middle')+U.text(400,190,v.bytes+' bytes/request','middle')+U.text(680,190,f.victimMbps+' Mbit/s','middle')+U.text(40,255,`Request rate = ${f.pps.toFixed(1)} packets/s`)+U.text(40,300,'The request carries the spoofed victim source address.'),'Reflection redirects amplified responses toward a victim',800,340),stats:[['Request packet rate',f.pps.toFixed(1)+' packets/s'],['Victim response traffic',f.victimMbps+' Mbit/s'],['Byte amplification',v.amplification+'×']],equation:'packets/s = input Mbit/s · 10⁶ / (8 · bytes/request); victim Mbit/s = input Mbit/s · byte amplification',note:'Decimal Mbit/s; the same accounting layer is used in request/response byte totals, with 8 bits per byte. No packet loss or reflector bottleneck; a fixed effective byte ratio includes all responses per request. Link framing and protocol overhead must be included consistently for a physical-link calculation. A SYN cookie protects half-open connection state, while packet-processing and link capacities require their own defenses.'};},checks:()=>[{name:'10 Mbit/s at 100 bytes is 12500 packets/s',pass:flood(10,100,30).pps===12500},{name:'30 times response amplification gives 300 Mbit/s',pass:flood(10,100,30).victimMbps===300}]});

  models.push({id:'worm-growth',controls:[ctl('initial','Initially infected hosts',1,100,1,10,'hosts'),ctl('doubling','Early doubling time',1,20,1,5,'min'),ctl('minutes','Elapsed time',0,60,1,20,'min'),ctl('logLimit','log₁₀ susceptible-host ceiling',3,6,1,5,'')],
    render(v,U){const limit=10**v.logLimit,n=worm(v.initial,v.doubling,v.minutes,limit);return{svg:U.plot([{name:'Clipped early exponential',points:U.range(120,t=>[60*t,worm(v.initial,v.doubling,60*t,limit)])},{name:'Chosen observation time',color:U.C.b,points:[[v.minutes,0],[v.minutes,limit]]}],{xmin:0,xmax:60,ymin:0,ymax:limit,xlabel:'Time since observation began (min)',ylabel:'Infected hosts (illustrative)',title:'Automatic propagation compounds while susceptible hosts remain'}),stats:[['Expected infected hosts',n.toFixed(1)],['Early doublings',(v.minutes/v.doubling).toFixed(2)],['Susceptible ceiling',limit.toLocaleString('en-US')]],equation:'Early phase I(t) = I₀ · 2^(t/d); displayed I = min(N, I(t)); t and doubling time d are minutes.',note:'An early-growth illustration with a hard susceptible-host ceiling N. This clipping is a visual bound, not a full epidemic or network model. Real growth depends on reachable vulnerable hosts, scanning, patching, segmentation, failed exploits and removal. Botnet membership and command channels require separate observations from infection counts.'};},checks:()=>[{name:'Four five-minute doublings multiply by sixteen',pass:worm(10,5,20,100000)===160},{name:'Displayed growth stays within susceptible ceiling',pass:worm(10,1,60,1000)===1000},{name:'Zero elapsed time preserves seed count',pass:worm(10,5,0,100000)===10}]});
})();
